@'
const fs=require('node:fs'),path=require('node:path');
const file='tools/reaudit-anki-source-tests.js';
const src=fs.readFileSync(file,'utf8');
const marker="main().catch(error=>{";
if(src.split(marker).length!==2)throw Error('nonunique source-harness terminal');
const api=new Function('require','__dirname',src.slice(0,src.indexOf(marker))+';return {C,build,reply,fact,ankiChain};')(require,path.resolve('tools'));
(async()=>{
 const source='The synthetic marker reads 600 units.';
 const quote='The synthetic marker reads 60';
 const state=await api.build({pages:[source],verifyPass:true,responses:[{conditions:[]},{missed:[{conditionName:'Signal',...api.fact('The synthetic marker reads 60 units.',{sourceQuote:quote})}]}]});
 console.log(JSON.stringify({case:'quote-trailing-token-prefix',source,quote,accepted:api.C.kbQuoteInSource(quote,api.C.kbNormForMatch(source),api.C.kbDehyphNormForMatch(source)),published:state.published,diagnostics:state.diag,error:state.error,warnings:state.warnings},null,2));
 const source2='The synthetic marker reads 160 units.';
 const quote2='60 units';
 console.log(JSON.stringify({case:'short-quote-control',accepted:api.C.kbQuoteInSource(quote2,api.C.kbNormForMatch(source2))}));
})();
